package com.aliplankstu.qingping;
import android.app.*;import android.os.*;import android.provider.Settings;import android.content.*;import android.view.*;import android.widget.*;
public class MainActivity extends Activity { TextView count; public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(36,50,36,30);l.setBackgroundColor(0xfff5f7fa); TextView title=new TextView(this);title.setText("清屏");title.setTextSize(30);title.setTextColor(0xff202938);l.addView(title);TextView sub=new TextView(this);sub.setText("开屏广告辅助拦截 · 0.1.0");sub.setTextSize(16);sub.setPadding(0,12,0,30);l.addView(sub);Button enable=new Button(this);enable.setText("开启无障碍拦截");enable.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));l.addView(enable);count=new TextView(this);count.setTextSize(20);count.setPadding(0,35,0,20);l.addView(count);Button reset=new Button(this);reset.setText("清零统计");reset.setOnClickListener(v->{getSharedPreferences("stats",0).edit().putInt("hits",0).apply();refresh();});l.addView(reset);TextView note=new TextView(this);note.setText("说明：Android 不允许普通应用直接屏蔽所有广告。本版本仅尝试识别可关闭按钮并点击；效果因应用而异。请勿对不熟悉的按钮自动操作。");note.setPadding(0,35,0,0);l.addView(note);setContentView(l);refresh();}void refresh(){count.setText("已尝试拦截："+getSharedPreferences("stats",0).getInt("hits",0)+" 次");}protected void onResume(){super.onResume();if(count!=null)refresh();}}